-void InhibitMonitor::inhibit(const QString &reason, bool isSilent)
+QDateTime InhibitMonitor::inhibitedUntil() const
 {
+    return m_inhibitedUntil;
+}
+
+void InhibitMonitor::inhibit(const QString &reason, bool isSilent, const QDateTime &until)
+{
+    setInhibitedUntil(until);
     beginSuppressingSleep(reason, isSilent);
     beginSuppressingScreenPowerManagement(reason);
 }

 void InhibitMonitor::uninhibit(bool isSilent)
 {
+    setInhibitedUntil({});
     stopSuppressingSleep(isSilent);
     stopSuppressingScreenPowerManagement();
 }
@@ -169,4 +178,30 @@ void InhibitMonitor::stopSuppressingScreenPowerManagement()
     });
 }

+void InhibitMonitor::setInhibitedUntil(const QDateTime &until)
+{
+    if (m_inhibitedUntil != until) {
+        m_inhibitedUntil = until;
+        Q_EMIT inhibitedUntilChanged(until);
+    }
+    checkInhibitionExpiry();
+}
+
+void InhibitMonitor::checkInhibitionExpiry()
+{
+    if (!m_inhibitedUntil.isValid()) {
+        m_expiryTimer.stop();
+        return;
+    }
+
+    const qint64 remaining = QDateTime::currentDateTime().msecsTo(m_inhibitedUntil);
+    if (remaining <= 0) {
+        uninhibit(false);
+        return;
+    }
+
+    // Check again at least every minute, as the timer doesn't advance while the system is asleep
+    m_expiryTimer.start(std::min<qint64>(remaining, 60 * 1000));
+}
+
